/**
 * Runtime support for vecDSL programs generated for Oracle AI Database 26ai, through node-oracledb in thin mode. Generated by
 * vecDSL 7. Do not edit.
 *
 * Every statement arrives as SQL text with positional bind variables (:1, :2, ... in textual order), identical in the Python,
 * TypeScript and Java programs. Lists and objects are bound as JSON text in CLOB binds; strings, numbers, booleans and null as
 * themselves. Queries return one JSON text per row (JSON_OBJECT ... RETURNING CLOB), which is decoded here. Each call is one
 * transaction: its statements run, then COMMIT (DDL statements commit by themselves); a failure rolls back.
 */
import { readFileSync } from "node:fs";
import oracledb from "oracledb";

const DIGITS = 6;
const BATCH = 500;
const CONNECT_TIMEOUT_SECONDS = 10;
const CALL_TIMEOUT_MS = 60000;
const TEXT_RESERVED = new Set(["ABOUT", "ACCUM", "AND", "BT", "BTG", "BTI", "BTP", "EQUIV", "FUZZY", "HASPATH", "INPATH", "MDATA",
  "MINUS", "NEAR", "NOT", "NT", "NTG", "NTI", "NTP", "OR", "PT", "RT", "SQE", "SYN", "TR", "TRSYN", "TT", "WITHIN"]);

oracledb.fetchAsString = [oracledb.CLOB];

export class UnsupportedFeature extends Error {}

export function unsupported(vendor: string, feature: string): never {
  throw new UnsupportedFeature(`${feature} is not supported for target ${vendor}`);
}

export function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) {
    throw new Error(`environment variable ${name} is not set`);
  }
  return value;
}

export interface Step {
  op?: string;
  sql: string;
  params?: unknown[];
  counter?: string;
  skipped?: number;
}

/** The database endpoint (Easy Connect string), the user and one connection; the password comes from the environment. */
export class Client {
  readonly callTimeout: number;
  private readonly password: string;
  private current: oracledb.Connection | undefined;

  constructor(readonly dsn: string, readonly user: string, passwordVariable: string, timeout?: number) {
    if (dsn.includes("@") || dsn.includes("://")) {
      throw new Error(`expected an Easy Connect string host:port/service without credentials, got ${dsn}`);
    }
    const password = process.env[passwordVariable];
    if (password === undefined) {
      throw new Error(`environment variable ${passwordVariable} is not set; it holds the password of ${user}`);
    }
    this.password = password;
    this.callTimeout = timeout ? Math.round(timeout * 1000) : CALL_TIMEOUT_MS;
  }

  async connection(): Promise<oracledb.Connection> {
    if (this.current === undefined) {
      this.current = await oracledb.getConnection({ user: this.user, password: this.password, connectString: this.dsn,
        connectTimeout: CONNECT_TIMEOUT_SECONDS });
      this.current.callTimeout = this.callTimeout;
    }
    return this.current;
  }

  async close(): Promise<void> {
    if (this.current !== undefined) {
      await this.current.close();
      this.current = undefined;
    }
  }
}

export async function connect(options: { dsn: string; user: string; passwordVariable?: string; timeout?: number }): Promise<Client> {
  return new Client(options.dsn, options.user, options.passwordVariable ?? "VECDSL_ORACLEDB_PASSWORD", options.timeout);
}

/** Integral numbers stay integers and lists and objects become JSON text, so that the three languages send the same values. */
function plainJson(value: unknown): string {
  return JSON.stringify(value);
}

function bind(value: unknown): oracledb.BindParameter | string | number | boolean | null {
  if (value === undefined || value === null) {
    return null;
  }
  if (Array.isArray(value) || typeof value === "object") {
    return { type: oracledb.DB_TYPE_CLOB, val: plainJson(value) };
  }
  return value as string | number | boolean;
}

/** Result values in one form for every host language: numbers rounded to six decimals. */
function normalize(value: unknown): unknown {
  if (typeof value === "number") {
    if (!Number.isFinite(value) || Number.isInteger(value)) {
      return value;
    }
    const rounded = Number(value.toFixed(DIGITS));
    return Object.is(rounded, -0) ? 0 : rounded;
  }
  if (Array.isArray(value)) {
    return value.map(normalize);
  }
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(Object.entries(value as Record<string, unknown>).map(([key, item]) => [key, normalize(item)]));
  }
  return value;
}

async function run(connection: oracledb.Connection, sql: string, params: unknown[]): Promise<unknown[] | number> {
  const result = await connection.execute<unknown[]>(sql, params.map(bind), { outFormat: oracledb.OUT_FORMAT_ARRAY });
  if (result.rows !== undefined) {
    return result.rows.map((row) => (row[0] === null ? null : normalize(JSON.parse(row[0] as string))));
  }
  return result.rowsAffected ?? 0;
}

async function inTransaction(client: Client, steps: Step[], isolation?: string, settings?: Record<string, string>): Promise<(unknown[] | number)[]> {
  const connection = await client.connection();
  const timeout = settings?.call_timeout;
  connection.callTimeout = timeout ? Number(timeout) : client.callTimeout;
  try {
    if (isolation === "serializable") {
      await connection.execute("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE");
    }
    const results: (unknown[] | number)[] = [];
    for (const step of steps) {
      results.push(await run(connection, step.sql, step.params ?? []));
    }
    await connection.commit();
    return results;
  } catch (error) {
    await connection.rollback();
    throw error;
  } finally {
    connection.callTimeout = client.callTimeout;
  }
}

function counts(step: Step, changed: number): Record<string, number> {
  const result: Record<string, number> = { [step.counter as string]: changed };
  if (step.skipped !== undefined) {
    result.skipped = ((step.params ?? [])[step.skipped] as unknown[]).length - changed;
  }
  return result;
}

/** The JSON values of a query's rows. */
export async function query(client: Client, args: { sql: string; params?: unknown[]; settings?: Record<string, string> }): Promise<unknown[]> {
  const rows = (await inTransaction(client, [args], undefined, args.settings))[0];
  return Array.isArray(rows) ? rows : [];
}

/** The JSON value of the first row, or null. */
export async function value(client: Client, args: { sql: string; params?: unknown[]; settings?: Record<string, string> }): Promise<unknown> {
  const rows = await query(client, args);
  return rows.length > 0 ? rows[0] : null;
}

/** Whether the count a query returns is above zero. */
export async function exists(client: Client, args: { sql: string; params?: unknown[] }): Promise<boolean> {
  return Boolean(await value(client, args));
}

/** A DML statement: {counter: changed rows}, and for an insert that ignores conflicts the records it skipped. */
export async function modify(client: Client, args: { sql: string; params?: unknown[]; counter: string; skipped?: number }): Promise<Record<string, number>> {
  const changed = (await inTransaction(client, [args]))[0];
  return counts(args, typeof changed === "number" ? changed : 0);
}

/** DDL statements and PL/SQL blocks in order; Oracle commits each DDL statement. */
export async function execute(client: Client, args: { steps: Step[] }): Promise<void> {
  await inTransaction(client, args.steps);
}

/** The statements of a vecDSL transaction in one Oracle transaction; any failure rolls back all of them. */
export async function transaction(client: Client, args: { steps: Step[]; isolation?: string }): Promise<unknown[]> {
  const outcomes = await inTransaction(client, args.steps, args.isolation);
  return args.steps.map((step, index) => {
    const outcome = outcomes[index];
    if (step.op === "modify") {
      return counts(step, typeof outcome === "number" ? outcome : 0);
    }
    if (step.op === "value") {
      return Array.isArray(outcome) && outcome.length > 0 ? outcome[0] : null;
    }
    return outcome;
  });
}

/** Records of a local JSON array or JSON Lines file (file:// URI or path). */
export async function readRecords(_client: Client, args: { location: string }): Promise<Record<string, unknown>[]> {
  const path = args.location.startsWith("file://") ? args.location.slice("file://".length) : args.location;
  const text = readFileSync(path, "utf-8");
  if (text.trimStart().startsWith("[")) {
    return JSON.parse(text) as Record<string, unknown>[];
  }
  return text.split(/\r?\n/).filter((line) => line.trim() !== "").map((line) => JSON.parse(line) as Record<string, unknown>);
}

/** A local file written in batches by one statement (the batch is the parameter at position rows), in one transaction. */
export async function importFile(client: Client, args: { sql: string; location: string; params: unknown[]; rows: number; counter: string;
  batch_size?: number }): Promise<Record<string, number>> {
  const records = await readRecords(client, args);
  const size = args.batch_size ?? BATCH;
  const steps: Step[] = [];
  for (let start = 0; start < records.length; start += size) {
    const params = [...args.params];
    params[args.rows] = records.slice(start, start + size);
    steps.push({ sql: args.sql, params });
  }
  const outcomes = await inTransaction(client, steps);
  return { [args.counter]: outcomes.reduce<number>((sum, count) => sum + (typeof count === "number" ? count : 0), 0) };
}

/** The words of a text: runs of letters, digits and underscores (Unicode categories L and N). */
function words(text: string): string[] {
  return text.match(/[\p{L}\p{N}_]+/gu) ?? [];
}

/**
 * An Oracle Text query of the words of an input: all (AND), any (ACCUM), a phrase, or the words NEAR each other in order within
 * span words; fuzzy expands each word of three or more characters with FUZZY. No operator of the input survives.
 */
export async function textQuery(
  _client: Client | undefined,
  args: { text: string; mode: string; stem?: boolean; fuzzy?: boolean; span?: number },
): Promise<string> {
  const found = words(args.text ?? "");
  if (found.length === 0) {
    throw new Error("a keyword search needs at least one word of letters or digits");
  }
  if (args.mode === "phrase") {
    if (args.span === undefined || found.length === 1) {
      return "{" + found.join(" ") + "}";
    }
    return "NEAR((" + found.map((word) => "{" + word + "}").join(", ") + "), " + String(args.span) + ", TRUE)";
  }
  const terms = found.map((word) => term(word, args.stem === true, args.fuzzy === true));
  return terms.join(args.mode === "any" ? " ACCUM " : " AND ");
}

function term(word: string, stem: boolean, fuzzy: boolean): string {
  if (TEXT_RESERVED.has(word.toUpperCase())) {
    return "{" + word + "}";
  }
  if (fuzzy && word.length >= 3) {
    return "fuzzy(" + word + ")";
  }
  return stem ? "$" + word : word;
}

/** A LIKE pattern (ESCAPE '\') of a wildcard: * any characters, ? one character, everything else literal. */
export async function wildcardPattern(_client: Client | undefined, args: { pattern: string }): Promise<string> {
  const escaped = args.pattern.replace(/\\/g, "\\\\").replace(/%/g, "\\%").replace(/_/g, "\\_");
  return escaped.replace(/\*/g, "%").replace(/\?/g, "_");
}
